1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.util.ArrayList;
5	import java.util.List;
6	import java.util.regex.Pattern;
7	
8	import net.officefloor.plugin.variable.Out;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.escalation.OwnerFieldsInvalidException;
11	import org.springframework.web.bind.annotation.RequestBody;
12	
13	/**
14	 * Rejects a create request that is missing or blank in any required owner field, before
15	 * {@link BuildOwner} runs. Reads the body once and republishes it for later steps.
16	 */
17	public class ValidateOwnerFields {
18	
19	    /** A syntactically valid address: local-part@domain with a dotted domain, no spaces. */
20	    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
21	
22	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
23	            throws OwnerFieldsInvalidException {
24	        List<String> errors = new ArrayList<>();
25	        checkRequired("firstName", request.getFirstName(), errors);
26	        checkRequired("lastName", request.getLastName(), errors);
27	        checkRequired("city", request.getCity(), errors);
28	        checkRequired("telephone", request.getTelephone(), errors);
29	        normalizeAddress(request, errors);
30	        normalizeTelephone(request, errors);
31	        normalizeEmail(request, errors);
32	        validatePostcode(request, errors);
33	        validateRegistrationDate(request, errors);
34	        if (!errors.isEmpty()) {
35	            throw new OwnerFieldsInvalidException(errors);
36	        }
37	        validated.set(request);
38	    }
39	
40	    private static void checkRequired(String field, String value, List<String> errors) {
41	        if (value == null || value.isBlank()) {
42	            errors.add(field);
43	        }
44	    }
45	
46	    /**
47	     * Normalizes the address (see {@link AddressNormalizer}) and stores the result back on
48	     * the request so later steps persist, compare and return the canonical form. The
49	     * address is required: a value that is blank after normalization is a 400 (adds an
50	     * "address" error) and is not stored back.
51	     */
52	    private static void normalizeAddress(OwnerFieldsDto request, List<String> errors) {
53	        String normalized = AddressNormalizer.normalize(request.getAddress());
54	        if (normalized.isEmpty()) {
55	            errors.add("address");
56	        }
57	        else {
58	            request.setAddress(normalized);
59	        }
60	    }
61	
62	    /**
63	     * Normalizes the telephone to E.164 form (see {@link TelephoneE164}), storing the
64	     * result back on the request so later steps persist and return it. A value that
65	     * cannot form a valid E.164 number is a 400 (adds a "telephone" error).
66	     */
67	    private static void normalizeTelephone(OwnerFieldsDto request, List<String> errors) {
68	        String telephone = request.getTelephone();
69	        if (telephone == null) {
70	            return;
71	        }
72	        String e164 = TelephoneE164.toE164(telephone);
73	        if (e164 != null) {
74	            request.setTelephone(e164);
75	        }
76	        else if (!errors.contains("telephone")) {
77	            errors.add("telephone");
78	        }
79	    }
80	
81	    /**
82	     * Email is optional. When present (non-blank) it must be a syntactically valid address;
83	     * an invalid value is a 400 (adds an "email" error). A valid value is stored lower-cased
84	     * back on the request so later steps persist and return it lower-cased.
85	     */
86	    private static void normalizeEmail(OwnerFieldsDto request, List<String> errors) {
87	        String email = request.getEmail();
88	        if (email == null || email.isBlank()) {
89	            return;
90	        }
91	        String trimmed = email.trim();
92	        if (EMAIL.matcher(trimmed).matches()) {
93	            request.setEmail(trimmed.toLowerCase());
94	        }
95	        else if (!errors.contains("email")) {
96	            errors.add("email");
97	        }
98	    }
99	
100	    /**
101	     * Postcode is optional. When present (non-blank) it must be a 4-digit value that is valid
102	     * for the owner's city per the fixed region ranges (see
103	     * {@link org.springframework.samples.petclinic.model.Postcode}); an out-of-range or
104	     * malformed value is a 400 (adds a "postcode" error). A valid value is stored trimmed back
105	     * on the request so later steps persist and return it. A city with no known region accepts
106	     * any 4-digit postcode, keeping the create request backward-compatible when absent.
107	     */
108	    /**
109	     * Registration date is optional (it defaults to the server's current date in
110	     * {@link BuildOwner} when absent). When supplied it must not be later than the server's
111	     * current date; a future value is a 400 (adds a "registrationDate" error).
112	     */
113	    private static void validateRegistrationDate(OwnerFieldsDto request, List<String> errors) {
114	        LocalDate registrationDate = request.getRegistrationDate();
115	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
116	            errors.add("registrationDate");
117	        }
118	    }
119	
120	    private static void validatePostcode(OwnerFieldsDto request, List<String> errors) {
121	        String postcode = request.getPostcode();
122	        if (postcode == null || postcode.isBlank()) {
123	            return;
124	        }
125	        String trimmed = postcode.trim();
