14	/**
15	 * When a create request opts in via {@code sharesHousehold}, links the new owner into
16	 * the household of the existing same-lastName owner(s) at the same address by assigning
17	 * them all a shared {@code householdId}. Runs after {@link BuildOwner} (so the entity
18	 * exists) and before {@link SaveOwner} (so the new owner is persisted with the id).
19	 *
20	 * <p>The household is keyed on the normalized last name and address. If an existing housemate already
21	 * carries a {@code householdId} it is reused; otherwise a stable id is derived from the
22	 * household key and back-filled onto the existing housemates, so every member — the new
23	 * owner and each prior one — shares one identifier. A request that does not opt in is
24	 * left with a null {@code householdId}.
25	 */
26	public class AssignHousehold {
27	
28	    public void service(@Val OwnerFieldsDto request, @Val Owner owner,
29	            OwnerRepository ownerRepository) {
30	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
31	            return;
32	        }
33	        String lastName = normalize(owner.getLastName());
34	        String address = normalize(owner.getAddress());
35	
36	        List<Owner> housemates = new ArrayList<>();
37	        String existingId = null;
38	        for (Owner existing : ownerRepository.findAll()) {
39	            if (lastName.equals(normalize(existing.getLastName()))
40	                    && address.equals(normalize(existing.getAddress()))) {
41	                housemates.add(existing);
42	                if (existingId == null && existing.getHouseholdId() != null) {
43	                    existingId = existing.getHouseholdId();
44	                }
45	            }
46	        }
47	
48	        String householdId = existingId != null ? existingId : deriveHouseholdId(lastName, address);
49	        owner.setHouseholdId(householdId);
50	        for (Owner mate : housemates) {
51	            if (!householdId.equals(mate.getHouseholdId())) {
52	                mate.setHouseholdId(householdId);
53	                ownerRepository.save(mate);
54	            }
55	        }
56	    }
57	
58	    /**
59	     * A stable identifier for a household, derived deterministically from its normalized
60	     * last name and address so the same household always yields the same id.
61	     */
62	    private static String deriveHouseholdId(String lastName, String address) {
63	        String key = lastName + "|" + address;
64	        try {
65	            byte[] digest = MessageDigest.getInstance("SHA-256")
66	                    .digest(key.getBytes(StandardCharsets.UTF_8));
67	            StringBuilder sb = new StringBuilder("HH-");
68	            for (int i = 0; i < 8; i++) {
69	                sb.append(String.format("%02X", digest[i]));
70	            }
71	            return sb.toString();
72	        }
73	        catch (NoSuchAlgorithmException e) {
74	            throw new IllegalStateException("SHA-256 not available", e);
75	        }
76	    }
77	
78	    /** Lower-cased, trimmed, with internal whitespace runs collapsed to a single space. */
79	    private static String normalize(String value) {
80	        if (value == null) {
81	            return "";
82	        }
83	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
84	    }
85	}
