8	import org.springframework.samples.petclinic.model.Locality;
9	import org.springframework.samples.petclinic.model.Owner;
10	
11	/**
12	 * Assigns the owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>}: REGION is
13	 * the region code derived from the owner's postcode (see {@link Locality#regionOf}) and
14	 * HASH8 is the first 8 upper-case hexadecimal characters of the SHA-256 digest over the
15	 * concatenation of the owner's normalized (E.164) telephone and lastName (e.g.
16	 * {@code NSW-1A2B3C4D}). There are no sequence numbers — the same telephone and last name
17	 * in the same region always yield the same code. Runs after {@link BuildOwner} (so the
18	 * telephone is already normalized) and before {@link SaveOwner}.
19	 */
20	public class AssignCustomerCode {
21	
22	    public void service(@Val Owner owner) {
23	        String region = Locality.regionOf(owner.getPostcode());
24	        String hash8 = hash8(nullToEmpty(owner.getTelephone()) + nullToEmpty(owner.getLastName()));
25	        owner.setCustomerCode(region + "-" + hash8);
26	    }
27	
28	    private static String nullToEmpty(String value) {
29	        return value == null ? "" : value;
30	    }
31	
32	    /** The first 8 upper-case hex characters of SHA-256 over the UTF-8 bytes of {@code value}. */
33	    private static String hash8(String value) {
34	        try {
35	            byte[] digest = MessageDigest.getInstance("SHA-256")
36	                    .digest(value.getBytes(StandardCharsets.UTF_8));
37	            StringBuilder sb = new StringBuilder(8);
38	            for (int i = 0; i < 4; i++) {
39	                sb.append(String.format("%02X", digest[i]));
40	            }
41	            return sb.toString();
42	        }
43	        catch (NoSuchAlgorithmException e) {
44	            throw new IllegalStateException("SHA-256 not available", e);
45	        }
46	    }
47	}
