3	/**
4	 * Derives an owner's {@code identityKey}: the single value all duplicate detection is
5	 * expressed through.
6	 *
7	 * <p>The key is {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
8	 * By the time an owner is built its telephone has been normalized to E.164 and its email
9	 * lower-cased, so those stored values are the normalized forms. A null email or a null
10	 * {@code householdId} contributes an empty segment.
11	 *
12	 * <p>Two owners are duplicates only when their <em>whole</em> keys are equal. Because the
13	 * telephone is part of the key, two members of the same household (same
14	 * {@code householdId}) with different telephones have different keys and are both allowed.
15	 */
16	public final class IdentityKey {
17	
18	    private IdentityKey() {
19	    }
20	
21	    /** The identity key for the given owner. */
22	    public static String of(Owner owner) {
23	        return segment(owner.getTelephone()) + "|" + segment(owner.getEmail()) + "|"
24	                + segment(owner.getHouseholdId());
25	    }
26	
27	    private static String segment(String value) {
28	        return value == null ? "" : value;
29	    }
30	}
