1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	/**
6	 * Normalizes a street address to a canonical form.
7	 *
8	 * <p>Leading and trailing whitespace is trimmed and internal whitespace runs are
9	 * collapsed to a single space; the result is upper-cased; and common street-type
10	 * abbreviations are expanded token-wise ({@code ST -> STREET}, {@code RD -> ROAD},
11	 * {@code AVE -> AVENUE}).
12	 *
13	 * <p>For example {@code "  12  main  st "} becomes {@code "12 MAIN STREET"} and
14	 * {@code "7 elm ave"} becomes {@code "7 ELM AVENUE"}. An address that is empty or all
15	 * whitespace (or {@code null}) normalizes to the empty string.
16	 */
17	final class AddressNormalizer {
18	
19	    /** Abbreviation (upper-cased) -> expanded street type. */
20	    private static final Map<String, String> ABBREVIATIONS =
21	            Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
22	
23	    private AddressNormalizer() {
24	    }
25	
26	    /**
27	     * Returns the normalized form of {@code raw}, or the empty string when it is
28	     * {@code null} or blank after trimming.
29	     */
30	    static String normalize(String raw) {
31	        if (raw == null) {
32	            return "";
33	        }
34	        String collapsed = raw.trim().replaceAll("\\s+", " ").toUpperCase();
35	        if (collapsed.isEmpty()) {
36	            return "";
37	        }
38	        String[] tokens = collapsed.split(" ");
39	        for (int i = 0; i < tokens.length; i++) {
40	            String expanded = ABBREVIATIONS.get(tokens[i]);
41	            if (expanded != null) {
42	                tokens[i] = expanded;
43	            }
44	        }
45	        return String.join(" ", tokens);
46	    }
47	}
