1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.LinkedHashMap;
4	import java.util.Map;
5	
6	/**
7	 * Normalizes a telephone number to E.164 form.
8	 *
9	 * <p>Spaces, dashes and brackets are stripped. A value that already carries a leading
10	 * {@code '+'} keeps its country code as given; otherwise country code {@code +61} is
11	 * assumed and a single leading {@code '0'} is dropped from the national digits. The
12	 * result must contain 8 to 15 digits after the {@code '+'}; anything else is not a
13	 * valid E.164 number.
14	 *
15	 * <p>Where the country code is known its national-number length is enforced exactly:
16	 * {@code +61} (Australia) requires 9 national digits and {@code +1} (NANP) requires 10.
17	 * A number whose national part is the wrong length for its country code is not a valid
18	 * E.164 number. Country codes not listed here are only bound by the general 8-to-15
19	 * total-digit rule.
20	 *
21	 * <p>For example {@code "0412 345 678"} becomes {@code "+61412345678"} and
22	 * {@code "+64 21 123 456"} becomes {@code "+6421123456"}.
23	 */
24	final class TelephoneE164 {
25	
26	    /**
27	     * Country code (digits after the {@code '+'}) to its required national-number length.
28	     * The prefixes here are mutually exclusive (no number starts with more than one), so
29	     * ordering does not affect matching.
30	     */
31	    private static final Map<String, Integer> NATIONAL_LENGTH = new LinkedHashMap<>();
32	
33	    static {
34	        NATIONAL_LENGTH.put("1", 10); // NANP
35	        NATIONAL_LENGTH.put("61", 9); // Australia
36	    }
37	
38	    private TelephoneE164() {
39	    }
40	
41	    /**
42	     * Returns the E.164 form of {@code raw}, or {@code null} when it cannot form a valid
43	     * E.164 number (including a {@code null} input).
44	     */
45	    static String toE164(String raw) {
46	        if (raw == null) {
47	            return null;
48	        }
49	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
50	        if (cleaned.isEmpty()) {
51	            return null;
52	        }
53	        String digits;
54	        if (cleaned.charAt(0) == '+') {
55	            digits = cleaned.substring(1);
56	        }
57	        else {
58	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
59	            digits = "61" + national;
60	        }
61	        if (digits.isEmpty() || !digits.chars().allMatch(c -> c >= '0' && c <= '9')) {
62	            return null;
63	        }
64	        if (digits.length() < 8 || digits.length() > 15) {
65	            return null;
66	        }
67	        for (Map.Entry<String, Integer> country : NATIONAL_LENGTH.entrySet()) {
68	            String code = country.getKey();
69	            if (digits.startsWith(code)) {
70	                if (digits.length() - code.length() != country.getValue()) {
71	                    return null;
72	                }
73	                break;
74	            }
75	        }
76	        return "+" + digits;
77	    }
78	}
